ValidationRule.errorConditionFormula:
AND(
  /* Fire only on existing records */
  NOT(ISNEW()),

  /* Scope to General Task record type only */
  RecordType.DeveloperName = "General",

  /* Fire only when Description (Area__c) changes */
  ISCHANGED(Area__c),

  /* Block everyone after completion */
  OR(
    ISPICKVAL(Status, "Completed"),
    ISPICKVAL(PRIORVALUE(Status), "Completed")
  )
)
